ASSERT
  (SELECT COUNT(*)=2000000
   AND COUNT(DISTINCT document_id)=2000000
   AND COUNTIF(market_anchor_date IS NULL
               OR market_day20_date IS NULL
               OR market_anchor_date>market_day20_date
               OR market_day20_date>=DATE '2026-10-30')=0
   FROM `${dataset}.corpus_documents`) AS 'Every historical 20-session outcome must mature before the saved query source day';


CREATE TEMP TABLE verification_bindings AS
SELECT
  q.query_document_id AS query_document_id,
  q.query_rank AS query_rank,
  q.query_request_id AS query_request_id,
  q.observed_at AS observed_at,
  q.observed_day AS observed_day,
  q.document_url AS document_url,
  q.title AS title,
  q.metadata_text AS metadata_text,
  q.metadata_sha256 AS metadata_sha256,
  q.lex_tokens AS lex_tokens,
  q.quality_flags AS quality_flags,
  q.source_record_key AS source_record_key,
  q.source_revision_key AS source_revision_key,
  n.raw_revision_sha256 AS raw_revision_sha256,
  ARRAY
  (SELECT DISTINCT normalized_label
   FROM
     (SELECT TRIM(REGEXP_REPLACE(NORMALIZE_AND_CASEFOLD(label, NFKC), r'[\s\p{Z}\x{0085}\x{001C}-\x{001F}]+', ' ')) AS normalized_label
      FROM UNNEST(p.p.themes) AS label)
   WHERE normalized_label!=''
   ORDER BY normalized_label) AS themes
FROM `${baseline_dataset}.eval500_query_documents_v01` AS q
JOIN `${baseline_dataset}.eval500_normalized_v01` AS n ON n.document_id=q.query_document_id
AND n.source_revision_key=q.source_revision_key
AND n.metadata_sha256=q.metadata_sha256
AND n.metadata_text=q.metadata_text
AND n.admissible
JOIN `${baseline_dataset}.eval500_parsed_v01` AS p ON p.raw_revision_sha256=n.raw_revision_sha256;

ASSERT
  (SELECT COUNT(*)=500
   AND COUNT(DISTINCT b.query_document_id)=500
   AND COUNTIF(b.raw_revision_sha256 IS NULL
               OR b.observed_at<TIMESTAMP '2026-10-30T23:00:00+00:00'
               OR b.observed_at>=TIMESTAMP '2026-10-31T00:00:00+00:00')=0
   FROM verification_bindings AS b) AS 'Each saved query must bind exactly its selected normalized and parsed revision before filtering';


