WHERE ARRAY_LENGTH(s.matched_rule_ids)>0;

ASSERT
  (SELECT COUNT(*) BETWEEN 1 AND 500
   FROM `${dataset}.filtered_verify_query_documents_v01`) AS 'Expanded filtering retained no saved query documents';


CREATE TABLE `${dataset}.filtered_verify_query_vectors_v01` CLUSTER BY query_request_id AS WITH counts AS
  (SELECT
     q.query_request_id AS query_request_id,
     COUNT(*) AS document_uses
   FROM `${dataset}.filtered_verify_query_documents_v01` AS q
   GROUP BY q.query_request_id)
SELECT
  v.query_request_id AS query_request_id,
  v.embedding AS embedding,
  n.document_uses AS document_uses,
  LOWER(TO_HEX(SHA256(TO_JSON_STRING(v.embedding)))) AS vector_sha256
FROM `${baseline_dataset}.eval500_query_vectors_v01` AS v
JOIN counts AS n ON n.query_request_id=v.query_request_id;


CREATE TABLE `${dataset}.filtered_verify_queries_v01` CLUSTER BY
  query_key,
  query_document_id AS WITH normalized AS
  (SELECT
     q.query_document_id AS query_document_id,
     q.query_request_id AS query_request_id,
     TO_JSON_STRING(ARRAY
                      (SELECT DISTINCT token
                       FROM UNNEST(q.lex_tokens) AS token
                       ORDER BY token)) AS lexical_terms_json
   FROM `${dataset}.filtered_verify_query_documents_v01` AS q)
SELECT
  q.query_document_id AS query_document_id,
  q.query_request_id AS query_request_id,
  q.lexical_terms_json AS lexical_terms_json,
  DENSE_RANK() OVER(
                    ORDER BY q.lexical_terms_json) AS query_key
FROM normalized AS q;


CREATE TABLE `${dataset}.filtered_verify_query_terms_v01` CLUSTER BY
  term_key,
  query_key AS
SELECT DISTINCT
  q.query_key AS query_key,
  t.term_key AS term_key
FROM `${dataset}.filtered_verify_queries_v01` AS q
CROSS JOIN UNNEST(JSON_VALUE_ARRAY(q.lexical_terms_json)) AS token
JOIN `${dataset}.filtered_stable_bm25_terms_v01` AS t ON t.term=token;


CREATE TABLE `${dataset}.filtered_verify_reference_documents_v01` AS WITH representatives AS
  (SELECT
     q.query_document_id AS query_document_id,
     q.query_rank AS query_rank,
     q.query_request_id AS query_request_id
   FROM `${dataset}.filtered_verify_query_documents_v01` AS q QUALIFY ROW_NUMBER() OVER(PARTITION BY q.query_request_id
                                                                                        ORDER BY q.query_rank, q.query_document_id)=1)
SELECT
  r.query_document_id AS query_document_id,
  r.query_rank AS query_rank,
  r.query_request_id AS query_request_id
FROM representatives AS r
ORDER BY
  SHA256(CONCAT('gkg-filtered-2m-reference32-v01-r01', '\n', r.query_request_id)),
  r.query_request_id
LIMIT 32;


CREATE TABLE `${dataset}.filtered_verify_manifest_v01` AS
SELECT
  'gkg-filtered-2m-verification-v01-r01' AS release,
  @contract_sha256 AS contract_sha256,
  'expanded' AS profile,
  'ed6f55b8ee8450f5faedb009d7f4ff1854d4707c5f0c8ab59755712d5b254b77' AS rules_sha256,
  'b935834ce400c38516af947df67c356c90f67bac60e0feb4e7ee4760c302e9f8' AS embedding_spec_sha256,
  500 AS saved_source_documents,

  (SELECT COUNT(*)
   FROM `${dataset}.filtered_verify_query_documents_v01`) AS qualifying_query_documents,

  (SELECT COUNT(*)
   FROM `${dataset}.filtered_verify_query_vectors_v01`) AS query_inputs,

  (SELECT COUNT(*)
   FROM `${dataset}.filtered_verify_reference_documents_v01`) AS reference_documents,
  TIMESTAMP '2026-10-30T23:00:00+00:00' AS source_window_start,
  TIMESTAMP '2026-10-31T00:00:00+00:00' AS source_window_end,
  TIMESTAMP '2026-10-31T00:29:01.596982+00:00' AS saved_source_as_of,
  DATE '2026-10-30' AS maturity_cutoff,
  CURRENT_TIMESTAMP() AS recorded_at_utc;

ASSERT
  (SELECT preparation_contract_errors=0
   FROM
     (WITH raw_vectors AS
        (SELECT v.query_request_id AS request_id, 0 AS batch_number, '' AS status, v.embedding AS embedding
         FROM `${dataset}.filtered_verify_query_vectors_v01` AS v), raw_checks AS
        (SELECT r.request_id AS request_id, r.batch_number AS batch_number, r.status AS status, r.embedding AS embedding, ARRAY_LENGTH(r.embedding) AS dimensions,
           (SELECT COUNTIF(x IS NULL
                           OR IS_NAN(x)
                           OR IS_INF(x))
            FROM UNNEST(r.embedding) AS x) AS invalid_components,
           (SELECT MAX(ABS(x))
            FROM UNNEST(r.embedding) AS x) AS scale
         FROM raw_vectors AS r), scaled_norms AS
        (SELECT r.request_id AS request_id, r.batch_number AS batch_number, r.status AS status, r.embedding AS embedding, r.dimensions AS dimensions, r.invalid_components AS invalid_components, IF(r.invalid_components=0
                                                                                                                                                                                                     AND r.scale>0
                                                                                                                                                                                                     AND NOT IS_NAN(r.scale)
                                                                                                                                                                                                     AND NOT IS_INF(r.scale), SAFE_MULTIPLY(r.scale, SQRT(
                                                                                                                                                                                                                                                            (SELECT SUM(POW(SAFE_DIVIDE(x, r.scale), 2))
                                                                                                                                                                                                                                                             FROM UNNEST(r.embedding) AS x))), NULL) AS vector_norm
         FROM raw_checks AS r), validated AS
        (SELECT n.request_id AS request_id, n.batch_number AS batch_number, n.status AS status, n.dimensions AS dimensions, n.invalid_components AS invalid_components, n.vector_norm AS vector_norm, COALESCE(n.status=''
                                                                                                                                                                                                               AND n.dimensions=3072
                                                                                                                                                                                                               AND n.invalid_components=0
                                                                                                                                                                                                               AND n.vector_norm>0
                                                                                                                                                                                                               AND NOT IS_NAN(n.vector_norm)
                                                                                                                                                                                                               AND NOT IS_INF(n.vector_norm), FALSE) AS valid, LOWER(TO_HEX(SHA256(TO_JSON_STRING(n.embedding)))) AS vector_sha256
         FROM scaled_norms AS n), documents AS
        (SELECT COUNT(*) AS query_documents, COUNT(DISTINCT q.query_document_id) AS distinct_query_documents, COUNT(DISTINCT q.query_request_id) AS requested_inputs, COUNTIF(q.metadata_text IS NULL
                                                                                                                                                                              OR q.metadata_text=''
                                                                                                                                                                              OR BYTE_LENGTH(q.metadata_text)>6000
                                                                                                                                                                              OR q.metadata_sha256 IS DISTINCT
                                                                                                                                                                              FROM LOWER(TO_HEX(SHA256(q.metadata_text)))
                                                                                                                                                                              OR q.query_request_id IS DISTINCT
                                                                                                                                                                              FROM LOWER(TO_HEX(SHA256(CONCAT('{"autoTruncate":false,"endpoint":"gemini-embedding-2","outputDimensionality":3072,"representation_version":"gkg-bq-metadata-v03-total-first-complete-labels-6000utf8","task_configuration":"service_default_no_task_parameter"}', '\n', q.metadata_sha256))))
                                                                                                                                                                              OR ARRAY_LENGTH(q.lex_tokens) IS NULL
                                                                                                                                                                              OR ARRAY_LENGTH(q.lex_tokens)=0
                                                                                                                                                                              OR ARRAY_LENGTH(q.matched_rule_ids) IS NULL
                                                                                                                                                                              OR ARRAY_LENGTH(q.matched_rule_ids)=0
                                                                                                                                                                              OR q.observed_at<TIMESTAMP '2026-10-30T23:00:00+00:00'
                                                                                                                                                                              OR q.observed_at>=TIMESTAMP '2026-10-31T00:00:00+00:00'
                                                                                                                                                                              OR q.source_revision_key IS NULL
                                                                                                                                                                              OR q.raw_revision_sha256 IS NULL) AS query_binding_errors
         FROM `${dataset}.filtered_verify_query_documents_v01` AS q), vectors AS
        (SELECT COUNT(*) AS query_inputs, COUNT(DISTINCT v.request_id) AS distinct_query_inputs, COUNTIF(NOT v.valid) AS vector_errors
         FROM validated AS v), missing AS
        (SELECT COUNTIF(v.query_request_id IS NULL) AS missing_query_vectors
         FROM `${dataset}.filtered_verify_query_documents_v01` AS q
         LEFT JOIN `${dataset}.filtered_verify_query_vectors_v01` AS v ON v.query_request_id=q.query_request_id), references AS
        (SELECT COUNT(*) AS reference_documents, COUNT(DISTINCT r.query_request_id) AS distinct_reference_requests, COUNTIF(q.query_document_id IS NULL
                                                                                                                            OR q.query_request_id IS DISTINCT
                                                                                                                            FROM r.query_request_id) AS reference_errors
         FROM `${dataset}.filtered_verify_reference_documents_v01` AS r
         LEFT JOIN `${dataset}.filtered_verify_query_documents_v01` AS q ON q.query_document_id=r.query_document_id), lexical AS
        (SELECT
           (SELECT COUNTIF(q.query_document_id IS NULL
                           OR l.query_document_id IS NULL
                           OR q.query_request_id IS DISTINCT
                           FROM l.query_request_id
                           OR l.lexical_terms_json IS DISTINCT
                           FROM TO_JSON_STRING(ARRAY
                                                 (SELECT DISTINCT token
                                                  FROM UNNEST(q.lex_tokens) AS token
                                                  ORDER BY token)))
            FROM `${dataset}.filtered_verify_query_documents_v01` AS q
            FULL OUTER JOIN `${dataset}.filtered_verify_queries_v01` AS l ON l.query_document_id=q.query_document_id) +
           (SELECT COUNT(*)
            FROM
              (SELECT t.query_key, t.term_key, COUNT(*) AS pairs
               FROM `${dataset}.filtered_verify_query_terms_v01` AS t
               GROUP BY t.query_key, t.term_key
               HAVING COUNT(*)!=1)) AS lexical_mapping_errors), history AS
        (SELECT COUNTIF(h.market_day20_date IS NULL
                        OR h.market_day20_date>=DATE '2026-10-30') AS history_maturity_errors
         FROM `${dataset}.corpus_documents` AS h), manifest AS
        (SELECT IF(COUNT(*)=1
                   AND COUNTIF(m.release='gkg-filtered-2m-verification-v01-r01'
                               AND m.contract_sha256=@contract_sha256
                               AND m.profile='expanded'
                               AND m.rules_sha256='ed6f55b8ee8450f5faedb009d7f4ff1854d4707c5f0c8ab59755712d5b254b77'
                               AND m.embedding_spec_sha256='b935834ce400c38516af947df67c356c90f67bac60e0feb4e7ee4760c302e9f8'
                               AND m.saved_source_documents=500
                               AND m.qualifying_query_documents=d.query_documents
                               AND m.query_inputs=v.query_inputs
                               AND m.reference_documents=r.reference_documents
                               AND m.maturity_cutoff=DATE '2026-10-30'
                               AND m.source_window_start=TIMESTAMP '2026-10-30T23:00:00+00:00'
                               AND m.source_window_end=TIMESTAMP '2026-10-31T00:00:00+00:00'
                               AND m.saved_source_as_of=TIMESTAMP '2026-10-31T00:29:01.596982+00:00')=1, 0, 1) AS manifest_errors
         FROM `${dataset}.filtered_verify_manifest_v01` AS m
         CROSS JOIN documents AS d
         CROSS JOIN vectors AS v
         CROSS JOIN references AS r) SELECT d.query_documents AS query_documents, d.distinct_query_documents AS distinct_query_documents, v.query_inputs AS query_inputs, v.distinct_query_inputs AS distinct_query_inputs, r.reference_documents AS reference_documents, r.distinct_reference_requests AS distinct_reference_requests, d.query_binding_errors AS query_binding_errors, v.vector_errors AS vector_errors, x.missing_query_vectors AS missing_query_vectors, r.reference_errors AS reference_errors, l.lexical_mapping_errors AS lexical_mapping_errors, h.history_maturity_errors AS history_maturity_errors, m.manifest_errors AS manifest_errors, IF(d.query_documents BETWEEN 1 AND 500
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       AND d.query_documents=d.distinct_query_documents
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       AND d.query_binding_errors=0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       AND v.query_inputs=d.requested_inputs
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       AND v.query_inputs=v.distinct_query_inputs
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       AND v.vector_errors=0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       AND x.missing_query_vectors=0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       AND r.reference_documents=LEAST(32, v.query_inputs)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       AND r.distinct_reference_requests=r.reference_documents
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       AND r.reference_errors=0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       AND l.lexical_mapping_errors=0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       AND h.history_maturity_errors=0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       AND m.manifest_errors=0, 0, 1) AS preparation_contract_errors
      FROM documents AS d
      CROSS JOIN vectors AS v
      CROSS JOIN missing AS x
      CROSS JOIN references AS r
      CROSS JOIN lexical AS l
      CROSS JOIN history AS h
      CROSS JOIN manifest AS m
      LIMIT 1)) AS 'Filtered saved query preparation failed validation';
